#!/usr/bin/env python3
"""
Homicide worldwide, third patch (culprits), 17 October 2026. Needs the second
homicide patch (homicide_culprits2.py, already applied on main).

A row for the homicide map's figures within countries (59 countries and
Europe's regions), read from the same map with ?within=all; the reader can now
be told to wait for a map that fetches its data in parts.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTE = "## Homicide worldwide, third patch (17 October, a separate chat)\n\nNeeds the second homicide patch (guards on its heading). Not a numbered round;\nthis note goes at the end of this file. Files go into the maps repo by hand.\nNo tiles patch. No app.js?v= bump.\n\n- Owner, 17 October: add the Murder Accountability Project and the Global\n  Organized Crime Index, and every country's homicide figures below the\n  national level.\n- maps repo: homicide.html replaced; new folder homicide_within/ (61 files,\n  about 97 MB: one JSON per country, plus Canada's police-service tables in\n  CAN.in.0.json and CAN.in.1.json, read when that list is opened). The map\n  gains a fifth part, the Global Organized Crime Index (GI-TOC; every score\n  of 2021, 2023, 2025; no licence stated), and a \"Homicide within countries\"\n  list: 59 countries and Eurostat's NUTS regions, each loaded when ticked,\n  shaded per level by its most common figure; boxes are built in the browser\n  from compact tables; every row of each source file is in some box (checked\n  by the build). US counties: MAP's SHR76_25a (929,433 records) and UCR65_25,\n  counted by county, plus the owner's MAP county export.\n- The map reads itself two ways for this map. Read plainly (homicide_worldwide)\n  it draws its own five parts and none of the within files. Read with\n  ?within=all (new row homicide_within) it fetches every within file and draws\n  only those (21,067 areas, 140 overlays: country and level); the reader is\n  recognised by navigator.userAgent === \"node\". Boxes read that way are short\n  (the shading figure, how many figures, the table names) and link to the\n  full box in the map: homicide.html#w=<KEY>&l=<level>&a=<area>.\n  Local run: extract 93 s; places.geojson 44 MB (11 MB gzipped), boxes.json\n  22 MB.\n- pipeline/sources/_sitemap.py: spec_for passes a registry \"wait\" (ms) on to\n  extract.mjs, and the node timeout grows by it. registry.json: homicide_within\n  (url maps/main/homicide.html?within=all, wait 120000).\n- app.js: homicide_worldwide's note names the index; new row homicide_within\n  (SITE_MAPS, SHORT_NAMES, LAYER_KIND, LAYER_SITE, NOT_LIVE), PANEL_ORDER\n  \"homicide_worldwide\", \"homicide_within\", \"stand_your_ground\".\n- test.mjs: block \"homicide within countries (17 October)\"; the stand your\n  ground block allows the new row between it and the homicide row.\n"

DIFF = ""

FILES = ["map/app.js", "map/test.mjs", "pipeline/sitemaps/registry.json", "pipeline/sources/_sitemap.py"]


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("homicide3: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Homicide worldwide, second patch (17 October" not in h.read_text(encoding="utf-8"):
        sys.exit("homicide3: the second homicide patch must be applied first (homicide_culprits2.py)")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("homicide3: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", *FILES, check=False)
            sys.exit("homicide3: the diff did not apply:\n" + r.stdout + r.stderr)
        print("homicide3: applied")
    text = h.read_text(encoding="utf-8")
    if NOTE.split("\n", 1)[0] not in text:
        h.write_text(text.rstrip("\n") + "\n\n\n" + NOTE, encoding="utf-8")


if __name__ == "__main__":
    main()
